NSMXS010.ol:
#Global Variables
#GVAR_SSMM_M1_LastSampleTime
#GVAR_SSMM_M1_LastSampleVal
#GVAR_SSMM_M1_LastGradient
#GVAR_SSMM_M1_Ok
#
# Local Variables
# CONFIG
VAR_CycleTime := 1015.0;       # SSMM scrubbing cycle time
VAR_CycleMultiplier := 1.05;   # Multiplier, to avoid aliasing
VAR_LowerLim := 0.13;          # Lowest point at which we go OOL       
VAR_UpperLim := 0.2;           # Upper cut-off
# SSMM Memory Module Error Count TM
VAR_SSMM_M1_SampleTime := OPMCS_utc2obt(NSM00799.time) * 1.0;
VAR_SSMM_M1_SampleVal := NSM00799.raw;
#
# Sanity Checks on Globals
if (GVAR_SSMM_M1_LastSampleTime < 1.0) lor (GVAR_SSMM_M1_LastSampleTime > VAR_SSMM_M1_SampleTime) then
    GVAR_SSMM_M1_LastSampleTime := VAR_SSMM_M1_SampleTime;
    GVAR_SSMM_M1_LastSampleVal := VAR_SSMM_M1_SampleVal;
    GVAR_SSMM_M1_Gradient := 0.0;
    GVAR_SSMM_M1_Ok := 0;
    return(GVAR_Ok);
endif;
#
# Compute difference in error count
VAR_dx := VAR_SSMM_M1_SampleVal - GVAR_SSMM_M1_LastSampleVal;
# Handle wrap-around
if (VAR_dx < 0) then
    VAR_dx := 65535 + VAR_dx;
endif;
#
# Compute delta time
VAR_dt := VAR_SSMM_M1_SampleTime - GVAR_SSMM_M1_LastSampleTime;
#
# Compute gradient
VAR_gradient := VAR_dx/VAR_dt;
#
# Check over a period of at least the sample time (1015 seconds), otherwise return
if (VAR_dt < VAR_CycleTime*VAR_CycleMultiplier) then
    return(GVAR_SSMM_M1_Ok);    
endif;
#
#
# Store this sample & timestamp for next time
GVAR_SSMM_M1_LastSampleTime := VAR_SSMM_M1_SampleTime;
GVAR_SSMM_M1_LastSampleVal := VAR_SSMM_M1_SampleVal;
#
# Calculate the average of the last two points
VAR_avgGrad := (GVAR_SSMM_M1_LastGradient + VAR_gradient)/2;
#
# Store this gradient for the next time
GVAR_SSMM_M1_LastGradient := VAR_gradient;
#
# Return OK/NOK value based on the limits
if (VAR_avgGrad > VAR_LowerLim) land (VAR_avgGrad < VAR_UpperLim) then
    GVAR_SSMM_M1_Ok := 1;
else
    GVAR_SSMM_M1_Ok := 0;
endif;

return(GVAR_SSMM_M1_Ok);
